#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

/**
 * Problem: 23551 - Largest Square
 * 
 * 解題思路：
 * 1. 給定一個 M x N 的字元網格，以及多個查詢點 (r, c)。
 * 2. 對於每個 (r, c)，尋找以該點為中心、所有字元皆相同的最大正方形邊長。
 * 3. 由於中心點必須是正方形的對角線交點，因此正方形的邊長必定為奇數 (1, 3, 5, ...)。
 * 4. 演算法：
 *    - 從邊長 1 開始，逐漸擴大半徑 k (邊長 = 2k + 1)。
 *    - 對於每個 k，檢查正方形的四條邊界是否都在網格內，且字元是否與中心點 (r, c) 相同。
 *    - 一旦發現邊界超出範圍或字元不符，則停止並輸出前一個可行的邊長。
 */

void solve() {
    int m, n, q;
    cin >> m >> n >> q;
    vector<string> grid(m);
    for (int i = 0; i < m; i++) cin >> grid[i];

    cout << m << " " << n << " " << q << endl;
    while (q--) {
        int r, c;
        cin >> r >> c;
        char target = grid[r][c];
        int k = 0;
        while (true) {
            int nk = k + 1;
            if (r - nk < 0 || r + nk >= m || c - nk < 0 || c + nk >= n) break;

            bool ok = true;
            for (int i = r - nk; i <= r + nk; i++) {
                if (grid[i][c - nk] != target || grid[i][c + nk] != target) {
                    ok = false; break;
                }
            }
            if (!ok) break;
            for (int j = c - nk; j <= c + nk; j++) {
                if (grid[r - nk][j] != target || grid[r + nk][j] != target) {
                    ok = false; break;
                }
            }
            if (!ok) break;
            k = nk;
        }
        cout << 2 * k + 1 << endl;
    }
}

int main() {
    int t;
    if (cin >> t) {
        while (t--) solve();
    }
    return 0;
}

